method how_many_times(string: string, substring: string) returns (count: int)
    requires substring.Length > 0
    ensures count >= 0
    ensures count == CountOccurrences(string, substring)

    // Helper function to count occurrences
    function CountOccurrences(s: string, sub: string): int
        ensures result >= 0
    {
        var i := 0;
        var occurrences := 0;
        while i <= s.Length - sub.Length
            invariant 0 <= i <= s.Length - sub.Length
            invariant occurrences >= 0
        {
            if s.Substring(i, sub.Length) == sub {
                occurrences := occurrences + 1;
                i := i + 1; // Allow for overlapping occurrences
            } else {
                i := i + 1;
            }
        }
        return occurrences;
    }
